with recent_orders as (select * from orders where status = 'COMPLETED' and discount > 0.36), orders_stats as (select channel, count(case when channel = 'partner' then 1 end) as partner_count, min(amount) as min_amount from recent_orders group by channel) select channel, partner_count, min_amount from orders_stats where partner_count > 3 order by partner_count desc, channel limit 5;
